import torch
from torch import nn
def fit(optimizer_name):
    torch.manual_seed(5); model=nn.Linear(2,1); opt_cls={'SGD':torch.optim.SGD,'Adam':torch.optim.Adam,'AdamW':torch.optim.AdamW}[optimizer_name]; opt=opt_cls(model.parameters(),lr=0.01); x=torch.ones(4,2); y=torch.ones(4,1)
    for _ in range(5): opt.zero_grad(); loss=((model(x)-y)**2).mean(); loss.backward(); opt.step()
    return float(loss)
print({name: round(fit(name), 4) for name in ['SGD','Adam','AdamW']})

